class Resource extends Base {
 mount(){this._value??=this.number('start',50,5,95);const art=(finished)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 420" aria-hidden="true"><rect width="720" height="420" fill="${finished?'#9baf9d':'#162c34'}"/>${Array.from({length:14},(_,i)=>`<path d="M${i*60} 0v420M0 ${i*45}h720" stroke="${finished?'#879b8955':'#5b9bad22'}"/>`).join('')}<path d="M120 280 350 150l250 135-230 128Z" fill="${finished?'#728777':'none'}" stroke="${finished?'#334d3c':'#7bc5d0'}"/><path d="M180 245v-95l170-95 170 92v100l-170 98Z" fill="${finished?'#d4d7bd':'none'}" stroke="${finished?'#61715c':'#7bc5d0'}"/><path d="m180 150 170 92 170-95M350 242v103" fill="none" stroke="${finished?'#7c8d70':'#7bc5d0'}" stroke-width="2"/><path d="M240 185v96l64 35v-96M392 222v98l64-38v-98" fill="${finished?'#526a5d':'none'}" stroke="${finished?'#526a5d':'#7bc5d0'}"/>${finished?'<circle cx="570" cy="80" r="28" fill="#e1d5a4"/><path d="M555 305v-65m-22 28 22-28 22 28" stroke="#4f6958" stroke-width="12"/>':''}</svg>`;this.render(`<section class="scene"><header><span class="label">FROM INTENTION TO ATMOSPHERE</span><h2>A different way of seeing.</h2></header><div class="compare"><div class="image before">${art(false)}<span>01 / THE PLAN</span></div><div class="image after">${art(true)}<span>02 / THE FEELING</span></div><div class="divider"><button role="slider" aria-label="Comparison position" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50" aria-valuetext="50 percent after" tabindex="0">↔</button></div></div><footer><span>DRAG THE LENS / OR USE ARROW KEYS</span><output></output></footer></section>`,`.scene{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}header{padding:27px 28px}h2{font:400 clamp(24px,4vw,34px) Georgia;margin-top:10px}.compare{height:350px;position:relative;touch-action:none;overflow:hidden}.image{position:absolute;inset:0}.image svg,.image img{width:100%;height:100%;object-fit:cover;display:block}.image.after{clip-path:inset(0 0 0 var(--split,50%))}.image>span{position:absolute;bottom:20px;left:20px;color:#b9e3e4;font-size:8px;letter-spacing:1.4px}.image.after>span{left:auto;right:20px;color:#304634}.divider{position:absolute;left:var(--split,50%);top:0;bottom:0;width:2px;background:var(--accent);transform:translateX(-1px)}.divider button{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);border:3px solid var(--panel);background:var(--accent);color:#20352b;border-radius:50%;width:43px;height:43px;font-size:22px;box-shadow:0 3px 20px #0004;cursor:ew-resize}footer{display:flex;align-items:center;justify-content:space-between;padding:17px 22px;color:var(--muted);font-size:8px;letter-spacing:1px}output{color:var(--accent);font:11px ui-monospace}@media(max-width:480px){header{padding:22px}.compare{height:310px}.image span{font-size:6px;left:12px;bottom:15px;letter-spacing:.5px}.image.after>span{right:12px}footer{font-size:6px;padding:17px}}`);for(const type of ['before','after']){const src=this.getAttribute(type);if(src&&/^(https?:|\.\/|\/|data:image\/)/.test(src)){const img=document.createElement('img');img.src=src;img.alt=this.text(type+'-alt',type==='before'?'Before comparison':'After comparison');this.$('.'+type+' svg').replaceWith(img);}}
 const area=this.$('.compare');this.listen(area,'pointerdown',e=>{this.dragging=true;area.setPointerCapture(e.pointerId);this.move(e);});this.listen(area,'pointermove',e=>{if(this.dragging)this.move(e);});this.listen(area,'pointerup',()=>this.dragging=false);this.listen(area,'pointercancel',()=>this.dragging=false);this.listen(this.$('[role=slider]'),'keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();this.value=e.key==='Home'?0:e.key==='End'?100:this.value+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?10:2);});this.paint();}
 move(event){const box=this.$('.compare').getBoundingClientRect();this.value=(event.clientX-box.left)/box.width*100;}
 get value(){return this._value;}
 set value(value){this._value=clamp(Number(value)||0,0,100);if(this._connected){this.paint();this.emit('comparison-change',{value:Math.round(this._value)});}}
 paint(){this.$('.compare').style.setProperty('--split',`${this._value}%`);this.$('[role=slider]').setAttribute('aria-valuenow',String(Math.round(this._value)));this.$('[role=slider]').setAttribute('aria-valuetext',`${Math.round(this._value)} percent after`);this.$('output').textContent=`${Math.round(this._value)} / ${Math.round(100-this._value)}`;}
 configured(name){if(name==='start')this.value=this.number('start',50,0,100);}
}
